import heapq

def top_k_generator(nums, k):
    if k <= 0:
        return []
    max_heap = [-x for x in nums]
    heapq.heapify(max_heap)
    return [-heapq.heappop(max_heap) for _ in range(k)]

def top_k_optimized(nums, k):
    if k <= 0:
        return []
    max_heap = []
    for num in nums:
        heapq.heappush(max_heap, -num)
    return [-heapq.heappop(max_heap) for _ in range(k)]

print(top_k_optimized(range(1000000), 5))

